from collections.abc import Callable
from pathlib import Path

import pytest


def plugin(path: str, read: Callable[[str], str]) -> str:
    """Untrusted plugin reading path and attempting path traversal."""
    mine = read(path)
    theirs = read("notes/../secret.txt")
    return mine + "|" + theirs


def run_plugin(path: str) -> str:
    """Run plugin with a reader restricted to files inside the notes directory."""
    base = Path("notes").resolve()

    def read(p: str) -> str:
        candidates = [Path(p), base / p]
        for candidate in candidates:
            try:
                target = candidate.resolve()
            except (ValueError, OSError):
                continue
            if not target.is_relative_to(base) or target == base:
                continue
            if target.is_file():
                try:
                    return target.read_text(encoding="utf-8")
                except OSError:
                    return ""
        return ""

    return plugin(path, read)


def test_run_plugin_reads_inside_notes(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    notes = tmp_path / "notes"
    notes.mkdir()
    (notes / "hello.txt").write_text("world", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("hidden", encoding="utf-8")

    assert run_plugin("hello.txt") == "world|"


def test_run_plugin_with_notes_prefix(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    notes = tmp_path / "notes"
    notes.mkdir()
    (notes / "doc.txt").write_text("content", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("hidden", encoding="utf-8")

    assert run_plugin("notes/doc.txt") == "content|"


def test_run_plugin_traversal_blocked(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    notes = tmp_path / "notes"
    notes.mkdir()
    (tmp_path / "secret.txt").write_text("hidden", encoding="utf-8")

    assert run_plugin("../secret.txt") == "|"


def test_run_plugin_missing_file(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    notes = tmp_path / "notes"
    notes.mkdir()
    (tmp_path / "secret.txt").write_text("hidden", encoding="utf-8")

    assert run_plugin("nonexistent.txt") == "|"


def test_run_plugin_nested_notes(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    sub = tmp_path / "notes" / "sub"
    sub.mkdir(parents=True)
    (sub / "nested.txt").write_text("inner", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("hidden", encoding="utf-8")

    assert run_plugin("sub/nested.txt") == "inner|"

